import 'package:flutter/material.dart'; import 'package:share_plus/share_plus.dart'; import 'package:shared_preferences/shared_preferences.dart'; import '../services/audio_quran_service.dart'; import '../services/favorite_ayah_service.dart'; import '../services/quran_service.dart';
class QuranPage extends StatefulWidget{const QuranPage({super.key});@override State<QuranPage> createState()=>_QuranPageState();}
class _QuranPageState extends State<QuranPage>{List<SurahIndex> index=[];List<QuranSearchResult> results=[];final search=TextEditingController();bool loading=true,searching=false;int lastSurah=1,lastAyah=1;@override void initState(){super.initState();load();}@override void dispose(){search.dispose();super.dispose();}Future<void> load()async{final p=await SharedPreferences.getInstance();final i=await QuranService.loadQuranIndex();setState(()=>{index=i,lastSurah=p.getInt('last_surah_number')??1,lastAyah=p.getInt('last_ayah_number')??1,loading=false});}Future<void> open(int n,{int ayah=1})async{final s=await QuranService.loadSurah(n);if(!mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>SurahReaderPage(surah:s,initialAyah:ayah,onPositionChanged:({required surahNumber,required ayahNumber})async{final p=await SharedPreferences.getInstance();await p.setInt('last_surah_number',surahNumber);await p.setInt('last_ayah_number',ayahNumber);}))));}Future<void> doSearch(String q)async{final r=await QuranService.searchQuran(q);setState((){searching=q.trim().isNotEmpty;results=r;});}@override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());return Padding(padding:const EdgeInsets.all(16),child:Column(children:[Card(child:ListTile(leading:const Icon(Icons.bookmark,color:Colors.green),title:const Text('متابعة القراءة'),subtitle:Text('سورة $lastSurah، الآية $lastAyah'),onTap:()=>open(lastSurah,ayah:lastAyah))),const SizedBox(height:12),TextField(controller:search,decoration:const InputDecoration(hintText:'ابحث في القرآن',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()),onChanged:doSearch),const SizedBox(height:12),Expanded(child:searching?ListView(children:results.map((r)=>Card(child:ListTile(title:Text('سورة ${r.surahName}، آية ${r.ayahNumber}'),subtitle:Text(r.text,maxLines:2,overflow:TextOverflow.ellipsis),onTap:()=>open(r.surahNumber,ayah:r.ayahNumber)))).toList()):ListView.builder(itemCount:index.length,itemBuilder:(c,i){final s=index[i];return Card(child:ListTile(leading:CircleAvatar(child:Text('${s.number}')),title:Text('سورة ${s.name}'),subtitle:Text('${s.ayahCount} آية'),onTap:()=>open(s.number)));}))]));}}
class SurahReaderPage extends StatefulWidget{final Surah surah;final int initialAyah;final Future<void> Function({required int surahNumber,required int ayahNumber}) onPositionChanged;const SurahReaderPage({super.key,required this.surah,required this.initialAyah,required this.onPositionChanged});@override State<SurahReaderPage> createState()=>_SurahReaderPageState();}
class _SurahReaderPageState extends State<SurahReaderPage>{final audio=AudioQuranService();bool isAudioLoading=false;int? playing;@override void dispose(){audio.dispose();super.dispose();}Future<void> play(Ayah a)async{try{if(playing==a.number){await audio.stop();setState(()=>playing=null);return;}setState(()=>{isAudioLoading=true,playing=a.number});await audio.playAyah(surahNumber:widget.surah.number,ayahNumber:a.number,surahName:widget.surah.name);if(mounted)setState(()=>isAudioLoading=false);}catch(e){if(mounted){setState(()=>{isAudioLoading=false,playing=null});ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تشغيل الصوت: $e')));}}}Future<void> playSurah()async{setState(()=>isAudioLoading=true);await audio.playSurah(surah:widget.surah,startAyah:widget.initialAyah);if(mounted)setState(()=>isAudioLoading=false);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('سورة ${widget.surah.name}'),actions:[IconButton(icon:const Icon(Icons.stop),onPressed:()=>audio.stop())]),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:FilledButton.icon(onPressed:isAudioLoading?null:playSurah,icon:const Icon(Icons.playlist_play),label:const Text('تشغيل السورة'))),Expanded(child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:widget.surah.ayahs.length,itemBuilder:(c,i){final a=widget.surah.ayahs[i];return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[SelectableText('${a.text}  ﴿${a.number}﴾',textAlign:TextAlign.right,style:const TextStyle(fontSize:24,height:2)),Wrap(spacing:8,children:[OutlinedButton.icon(onPressed:()=>widget.onPositionChanged(surahNumber:widget.surah.number,ayahNumber:a.number),icon:const Icon(Icons.bookmark_add),label:const Text('حفظ')),OutlinedButton.icon(onPressed:()=>FavoriteAyahService.toggle(FavoriteAyah(surahNumber:widget.surah.number,surahName:widget.surah.name,ayahNumber:a.number,text:a.text)),icon:const Icon(Icons.star_border),label:const Text('مفضلة')),OutlinedButton.icon(onPressed:()=>Share.share('${a.text} ﴿${a.number}﴾\nسورة ${widget.surah.name}'),icon:const Icon(Icons.share),label:const Text('مشاركة')),FilledButton.icon(onPressed:isAudioLoading?null:()=>play(a),icon:Icon(playing==a.number?Icons.stop:Icons.play_arrow),label:Text(playing==a.number?'إيقاف':'استماع'))])])));} ))]));}
